head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[multiselect > P > mandatory]<br/>컴포넌트의 입력값 유효성 체크 시 입력값의 유/무를 확인하도록 설정합니다.",
    "validation" : [
        "validate(), validateObject() 메소드 실행 시 선택값이 없으면 유효성 검사가 실패로 처리됩니다.",
        "true 설정 시 컴포넌트의 입력값 유/무를 확인합니다.",
        "true 설정 시 'w2multiselect_mandatory' 클래스가 추가됩니다.",
        "false (default) 설정 시 컴포넌트의 입력값 유/무를 확인하지 않습니다.",
        "미설정 시 기본값(false)으로 동작하여 입력값 유/무를 확인하지 않습니다.",
        "선택값이 없는 경우 유효성 체크는 실패로 처리되고 displaymessage 속성에 따라 실패 메시지가 출력됩니다.",
        "시스템 기본 메시지는 '필수 입력 항목입니다' 이며, invalidMessage 또는 invalidMessageFunc 속성으로 메시지를 변경할 수 있습니다.",
        "mandatory 속성은 disabled 속성의 상태와 관계없이 유효성 검사에 적용됩니다.",
        "mandatory 속성은 readOnly 속성의 상태와 관계없이 유효성 검사에 적용됩니다.",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성 (createBasicMultiSelect 로 동적 생성, mandatory 속성 적용)
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // gdl_multiselect 재생성 (idempotent: 기존 dataList 제거 후 재생성)
    $c.gcm.createDataListMultiSelect();

    // 조건 설정
    let properties = {
        displaymessage: con_displaymessage.getText(),
        mandatory: con_mandatory.getText(),
        disabled: con_disabled.getText(),
        readOnly: con_readOnly.getText(),
    };

    let cList = $c.gcm.createCList(properties);

    $c.gcm.createBasicMultiSelect(cList);
}



scwin.btn_validate_onclick = function (e) {
    let rtn = target1.validate();

    if (rtn)
        wf_body_bottom.getObj("scwin").setReturnValue("validate check : PASS");
    else
        wf_body_bottom.getObj("scwin").setReturnValue("validate check : FAIL");
};



scwin.btn_validateObject_onclick = function (e) {
    let rtnObj = target1.validateObject();
    wf_body_bottom.getObj("scwin").setReturnValue("validateObject : " + rtnObj);

    if (rtnObj) {
        let callerId = rtnObj.callerId;
        let type = rtnObj.type;
        let value = rtnObj.value;

        wf_body_bottom.getObj("scwin").setReturnValue("callerId : " + callerId);
        wf_body_bottom.getObj("scwin").setReturnValue("type : " + type);
        wf_body_bottom.getObj("scwin").setReturnValue("value : " + value);
    }
};



scwin.btn_getClass_onclick = function (e) {
    let rtn = target1.render.className;

    wf_body_bottom.getObj("scwin").setReturnValue("className : " + rtn);
};
